//! The server the preview runs *inside* the pod, generated from the
//! checkout's config. It is plain ESM: the pod strips TypeScript, but the
//! less of its transform a generated file depends on, the fewer ways it can
//! surprise. Kept apart from the writer (`harness.ts`, which inlines Poder's
//! dist through a bundler-only glob) so the template stays importable from
//! plain runtimes — including its tests.

import { PROJECT_ROOT } from "../workspace/types";
import { poderBindings } from "./bindings";
import type { PreviewBinding } from "./config";
/** Where all binding data lives. Short on purpose: the pod's SQLite caps
 * full database paths well below POSIX (see the guard in `serverSource`),
 * so this stays a stub. `s` is not one of the directory names `openPod`
 * excludes, so a Counter value outlives the page reload. */
export const HARNESS_STATE_DIR = "/home/.noite/s";

/** What the generated server needs to know about the checkout. Every path is
 * absolute inside the pod. */
export interface HarnessPlan {
  /** The assets directory, when the app has one. */
  assets: string | null;
  bindings: PreviewBinding[];
  /** The Worker module, when the app has one. */
  entry: string | null;
  notFoundHandling: "404-page" | "none" | "single-page-application";
  /** The port the server listens on. */
  port: number;
}
/** The generated server. It reads its config from the literals below, serves
 * the assets first, then the Worker through Poder, and answers with the
 * fallback page when neither has anything — Cloudflare's own order. */
export const serverSource = (plan: HarnessPlan): string => {
  const assetsSource =
    plan.assets === null
      ? "const assets = null;"
      : `// The directory and fallback are literals, not constants: the pod
// strips a trailing key-colon-identifier property as if it were a type
// annotation, so an identifier in that position throws at startup.
const assets = createAssets({ directory: ${JSON.stringify(plan.assets)}, notFoundHandling: ${JSON.stringify(plan.notFoundHandling)} });`;
  const entrySource =
    plan.entry === null
      ? "const workerModule = null;"
      : `// The entry is whatever this checkout's config named, so it cannot be a
// static import: the specifier is chosen while the server is generated.
const workerModule = await import(${JSON.stringify(plan.entry)});`;
  const assetsBinding =
    plan.bindings.find((binding) => binding.kind === "assets")?.name ?? null;
  const secrets = plan.bindings
    .filter((binding) => binding.kind === "secret")
    .map((binding) => binding.name);
  return `// Generated by Noite's Preview panel. Rewritten on every start.
import { serve } from "srvx";

import { createAssets } from "./shims/assets.mjs";

const ASSETS_BINDING = ${JSON.stringify(assetsBinding)};
const PORT = ${plan.port};
const MISSING = ${JSON.stringify(secrets)};

const note = (line) => console.log("preview: " + line);
const bytes = (text) => new Response(text, { headers: { "content-type": "text/plain; charset=utf-8" }, status: 500 });

${assetsSource}

for (const name of MISSING) {
  note("the " + name + " secret is not set in Preview");
}

// The pod's SQLite is a WASM payload: preload it before anything else —
// Poder included — touches it. Poder is imported dynamically for the same
// reason: a static import would evaluate it (and its own node:sqlite
// import) before this preload runs.
const sqlite = await import("node:sqlite");
if (typeof sqlite.preloadSqlite === "function") {
  await sqlite.preloadSqlite();
}
const { createPoder, defaultSqliteDriver } = await import("./poder/index.mjs");

// The pod's SQLite caps full database paths far below POSIX (open fails
// past it with the engine's own wording), so every open goes through this
// guard: Poder's flat layout keeps them short, and anything longer fails
// here instead, naming the path. Delegation keeps the open itself on
// Poder's driver.
const SQLITE_PATH_CAP = 56;
const sqliteDriver = {
  open: (path) => {
    if (path.length > SQLITE_PATH_CAP) {
      throw new Error(
        "preview: sqlite path over the pod cap (" +
          path.length +
          " chars): " +
          path
      );
    }
    return defaultSqliteDriver.open(path);
  },
};

${entrySource}

// The options stay literals for the same reason as the assets above: the
// module and the log ride along after, by assignment rather than by value in
// the literal.
const options = {
  bindings: ${JSON.stringify(poderBindings(plan.bindings))},
  projectDir: ${JSON.stringify(PROJECT_ROOT)},
  stateDir: ${JSON.stringify(HARNESS_STATE_DIR)},
};
options.workerModule = workerModule;
options.log = note;
options.sqlite = sqliteDriver;
const poder = workerModule === null ? null : await createPoder(options);

if (poder !== null && assets !== null && ASSETS_BINDING !== null) {
  poder.env[ASSETS_BINDING] = { fetch: (request) => assets.fetch(request) ?? new Response("not found", { status: 404 }) };
}

const fallback = () => assets?.notFound() ?? bytes("Not found\\n");

const handle = async (request) => {
  if (assets !== null) {
    const hit = assets.fetch(request);
    if (hit !== null) {
      return hit;
    }
  }
  if (poder === null) {
    return fallback();
  }
  let response;
  try {
    response = await poder.fetch(request);
  } catch (error) {
    note(request.method + " " + new URL(request.url).pathname + " failed: " + (error?.message ?? error));
    if (error?.stack) {
      console.log(error.stack);
    }
    return bytes(String(error?.message ?? error) + "\\n");
  }
  if (response.status === 404 && assets !== null) {
    return assets.notFound() ?? response;
  }
  return response;
};

// The port stays a literal: the pod rewrites a port property holding an
// identifier into a bare port reference, which throws at startup.
serve({ fetch: handle, hostname: "127.0.0.1", port: ${plan.port} });
note("listening on " + PORT);
`;
};
